// [vite-esm] imports auto-generated by the 2026-07 Vite migration.
import "../state.js";
import "./main.js";
import "./candidate_ranker.js";

/**
 * Absence input tab — date picker + chip-style autocomplete for absent teachers.
 *
 * Mounts into the host element passed by main.js. Emits no events directly;
 * when the user clicks "Generate substitutions", we call
 *   candidate_ranker.rankAll(school, state.absent, dayOfWeek)
 * write the result into state.assignments, and invoke onGenerate() so the
 * shell can switch to the class-wise tab.
 *
 * Also fires `substitution:generate` so other modules can react.
 */
(function () {
  "use strict";
  const APP = window.APP;
  const S = window.Substitution;
  if (!APP || !S) return;
  const el = S.el, esc = S.esc;

  function render(host, state, onGenerate) {
    host.innerHTML = "";

    const school = APP.school;
    const teachers = (school && school.teachers) || [];

    // Sync state with saved absences if present
    if (school && school.absences && school.absences.length) {
      const savedTids = school.absences.filter(a => a.date === state.date).map(a => a.teacherId);
      for (const tid of savedTids) {
        if (!state.absent.includes(tid)) state.absent.push(tid);
      }
    }

    const day = S.ymdToDay(state.date);
    const dayLabel = day < 0 ? "Sunday (no school)" : (school._idx?.days?.[day] || "?");

    // ---- date row ----
    const dateInput = el("input", { type: "date", value: state.date,
      class: "chrx-sub-date",
      onchange: (e) => {
        state.date = e.target.value || S.todayYmd();
        state.absent = [];
        if (school && school.absences) {
          state.absent = school.absences.filter(a => a.date === state.date).map(a => a.teacherId);
        }
        // Rebuild the plan for the NEW day. Without this the previous day's
        // slots stayed on the board and the next action saved substitutes
        // against the wrong date (B-fix: date change left stale slots).
        if (S.loadPlan) {
          const fresh = S.loadPlan(school, state.date);
          state.slots = fresh.slots || [];
          state.assignments = fresh.assignments || [];
          state.dutyPool = fresh.dutyPool || [];
        }
        const d = S.ymdToDay(state.date);
        dayBadge.textContent = d < 0
          ? "Sunday (no school)"
          : (school._idx?.days?.[d] || "?");
        renderChips();
        updateGenerate();
      },
    });
    const dayBadge = el("span", { class: "chrx-sub-daybadge" }, dayLabel);

    host.appendChild(el("div", { class: "chrx-sub-row" },
      el("label", { class: "chrx-sub-lbl", for: "chrx-sub-date" }, "Date"),
      dateInput, dayBadge,
    ));

    // ---- chips ----
    const chips = el("div", { class: "chrx-sub-chips" });
    function renderChips() {
      chips.innerHTML = "";
      if (!state.absent.length) {
        chips.appendChild(el("span", { class: "chrx-sub-hint" },
          "No teachers selected. Use the search box below."));
        return;
      }
      state.absent.forEach(tid => {
        const t = (school._idx?.teacherById?.[tid]) || { id: tid, name: "?", abbr: "" };
        chips.appendChild(el("span", { class: "chrx-sub-chip" },
          el("span", { class: "chrx-sub-chip__nm" }, t.name || tid),
          t.abbr ? el("span", { class: "chrx-sub-chip__abbr" }, t.abbr) : null,
          el("button", { class: "chrx-sub-chip__x", "aria-label": "Remove",
            onclick: () => {
              state.absent = state.absent.filter(x => x !== tid);
              if (S.removeAbsence) S.removeAbsence(school, { date: state.date, teacherId: tid });
              renderChips();
              updateGenerate();
            }, type: "button" }, "×"),
        ));
      });
    }

    // ---- autocomplete ----
    const search = el("input", { type: "search",
      class: "chrx-sub-search",
      id: "chrx-sub-absent-search",
      "aria-label": "Search absent teachers",
      placeholder: "Type a teacher name…",
      autocomplete: "off",
    });
    const dropdown = el("div", { class: "chrx-sub-dropdown is-hidden" });

    function buildOptions(q) {
      const ql = q.trim().toLowerCase();
      const out = teachers.filter(t => {
        if (state.absent.includes(t.id)) return false;
        if (!ql) return true;
        return (t.name && t.name.toLowerCase().includes(ql)) ||
               (t.abbr && t.abbr.toLowerCase().includes(ql));
      }).slice(0, 30);

      dropdown.innerHTML = "";
      if (!out.length) {
        dropdown.appendChild(el("div", { class: "chrx-sub-opt is-empty" }, "No matches."));
        return;
      }
      out.forEach(t => {
        dropdown.appendChild(el("div", { class: "chrx-sub-opt",
          onclick: () => {
            if (!state.absent.includes(t.id)) {
              state.absent.push(t.id);
              if (S.recordAbsence) {
                // Carry the reason AND the absent-periods selection made before
                // the teacher was added; otherwise the day is covered in full.
                const spec = (!state.absentFrom && !state.absentTo)
                  ? "all"
                  : `${state.absentFrom || 1}-${state.absentTo || 99}`;
                S.recordAbsence(school, {
                  date: state.date,
                  teacherId: t.id,
                  type: state.absentType || "Sick",
                  periods: spec,
                });
              }
            }
            search.value = "";
            dropdown.classList.add("is-hidden");
            renderChips();
            updateGenerate();
          } },
          el("span", { class: "chrx-sub-opt__nm" }, t.name || t.id),
          t.abbr ? el("span", { class: "chrx-sub-opt__abbr" }, t.abbr) : null,
        ));
      });
    }

    search.addEventListener("focus", () => {
      buildOptions(search.value);
      dropdown.classList.remove("is-hidden");
    });
    search.addEventListener("input", () => {
      buildOptions(search.value);
      dropdown.classList.remove("is-hidden");
    });
    search.addEventListener("keydown", (e) => {
      if (e.key === "Escape") { dropdown.classList.add("is-hidden"); return; }
      if (e.key === "Enter") {
        e.preventDefault();
        const first = dropdown.querySelector(".chrx-sub-opt:not(.is-empty)");
        if (first) first.click();
      }
    });
    document.addEventListener("click", (e) => {
      if (!host.contains(e.target)) return;
      if (e.target !== search && !dropdown.contains(e.target)) {
        dropdown.classList.add("is-hidden");
      }
    });

    // aSc "Copy yesterday's absents" + long-term absence (date range).
    const addDays = (ymd, n) => {
      const [y, m, d] = ymd.split("-").map(Number);
      const t = new Date(y, m - 1, d + n);
      return `${t.getFullYear()}-${String(t.getMonth() + 1).padStart(2, "0")}-${String(t.getDate()).padStart(2, "0")}`;
    };
    // aSc lets an absence cover PART of the day ("absent periods 3-5"); a whole
    // day is the default. The selection is stored on the absence row and honoured
    // by the plan, so a teacher out for two periods is not replaced all day.
    const periodsPerDay = (school.bell?.periods || []).length || school.periodsPerDay || 8;
    state.absentFrom = state.absentFrom || "";
    state.absentTo = state.absentTo || "";
    const periodOptions = [""].concat(Array.from({ length: periodsPerDay }, (_, i) => String(i + 1)));
    const fromSel = el("select", { class: "chrx-sub-type", id: "chrx-sub-absent-from", "aria-label": "Absent from period",
      onchange: (e) => { state.absentFrom = e.target.value; applyPeriods(); } },
      ...periodOptions.map((p) => el("option", { value: p, selected: p === state.absentFrom ? "selected" : null }, p ? `P${p}` : "all day")));
    const toSel = el("select", { class: "chrx-sub-type", id: "chrx-sub-absent-to", "aria-label": "Absent to period",
      onchange: (e) => { state.absentTo = e.target.value; applyPeriods(); } },
      ...periodOptions.map((p) => el("option", { value: p, selected: p === state.absentTo ? "selected" : null }, p ? `P${p}` : "end")));

    function applyPeriods() {
      const from = state.absentFrom, to = state.absentTo;
      const spec = !from && !to ? "all" : `${from || 1}-${to || periodsPerDay}`;
      for (const tid of state.absent) {
        const row = (APP.school.absences || []).find(a => a.date === state.date && a.teacherId === tid);
        if (row) row.periods = spec;
      }
      if (S.loadPlan) {
        const fresh = S.loadPlan(APP.school, state.date);
        state.slots = fresh.slots || [];
        state.assignments = fresh.assignments || [];
      }
    }

    const copyPrev = el("button", { type: "button", class: "chrx-sub-btn", id: "chrx-sub-copy-prev",
      title: "Mark everyone absent on the previous school day as absent today",
      onclick: () => {
        let prev = addDays(state.date, -1);
        if (S.ymdToDay(prev) < 0) prev = addDays(prev, -1); // skip Sunday
        const ids = (school.absences || []).filter(a => a.date === prev).map(a => a.teacherId);
        let added = 0;
        for (const tid of ids) {
          if (state.absent.includes(tid)) continue;
          state.absent.push(tid);
          if (S.recordAbsence) S.recordAbsence(school, { date: state.date, teacherId: tid });
          added++;
        }
        copyPrev.textContent = ids.length ? `Copied ${added} from ${prev}` : `Nobody was absent on ${prev}`;
        renderChips();
        updateGenerate();
      } }, "Copy previous day's absentees");
    const untilInput = el("input", { type: "date", class: "chrx-sub-until", id: "chrx-sub-until",
      "aria-label": "Absent until" });
    const applyRange = el("button", { type: "button", class: "chrx-sub-btn", id: "chrx-sub-apply-range",
      title: "Record the selected teachers as absent on every school day up to this date",
      onclick: () => {
        const until = untilInput.value;
        if (!until || until <= state.date || !state.absent.length) return;
        let days = 0;
        for (let d = addDays(state.date, 1); d <= until; d = addDays(d, 1)) {
          if (S.ymdToDay(d) < 0) continue;
          for (const tid of state.absent) if (S.recordAbsence) S.recordAbsence(school, { date: d, teacherId: tid });
          days++;
        }
        applyRange.textContent = `Recorded for ${days} more day(s)`;
      } }, "Absent until…");

    host.appendChild(el("div", { class: "chrx-sub-row chrx-sub-row--col" },
      el("label", { class: "chrx-sub-lbl" }, "Absent teachers"),
      chips,
      el("div", { class: "chrx-sub-search-wrap" }, search, dropdown),
      el("div", { class: "chrx-sub-row" }, copyPrev, untilInput, applyRange),
    ));

    // ---- absence type (the standalone planner records why someone is out;
    // it is what the memo and the log show, and it drives nothing else) ----
    const ABSENCE_TYPES = ["Sick", "Leave", "Training", "Personal", "Other"];
    state.absentType = state.absentType || "Sick";
    const typeSelect = el("select", { class: "chrx-sub-type", "aria-label": "Absence type",
      onchange: (e) => { state.absentType = e.target.value; persistTypes(); } },
      ...ABSENCE_TYPES.map((t) => el("option", { value: t, selected: t === state.absentType ? "selected" : null }, t)));
    host.appendChild(el("div", { class: "chrx-sub-row" },
      el("label", { class: "chrx-sub-lbl" }, "Reason"),
      typeSelect,
      el("label", { class: "chrx-sub-lbl", for: "chrx-sub-absent-from" }, "Absent periods"),
      fromSel, el("span", { class: "chrx-sub-hint" }, "to"), toSel,
    ));

    function persistTypes() {
      const school2 = APP.school;
      for (const tid of state.absent) {
        const row = (school2.absences || []).find(a => a.date === state.date && a.teacherId === tid);
        if (row) row.type = state.absentType;
      }
    }

    // ---- on-duty pool: teachers already on duty that day are the cheapest,
    // best substitutes (the standalone planner pays them +200) ----
    if (!Array.isArray(state.dutyPool)) state.dutyPool = [];
    const dutyChips = el("div", { class: "chrx-sub-chips" });
    function renderDutyChips() {
      dutyChips.innerHTML = "";
      if (!state.dutyPool.length) {
        dutyChips.appendChild(el("span", { class: "chrx-sub-hint" }, "Nobody marked on duty for this day."));
        return;
      }
      for (const tid of state.dutyPool) {
        const t = school._idx?.teacherById?.[tid];
        dutyChips.appendChild(el("span", { class: "chrx-sub-chip" },
          el("span", { class: "chrx-sub-chip__nm" }, t?.name || tid),
          el("button", { class: "chrx-sub-chip__x", "aria-label": "Remove", type: "button",
            onclick: () => {
              state.dutyPool = state.dutyPool.filter(x => x !== tid);
              renderDutyChips();
            } }, "×"),
        ));
      }
    }
    const dutySearch = el("input", { type: "search", class: "chrx-sub-search", id: "chrx-sub-duty-search",
      placeholder: "Type a teacher on duty…", autocomplete: "off" });
    const dutyDropdown = el("div", { class: "chrx-sub-dropdown is-hidden" });
    function buildDutyOptions(q) {
      const ql = String(q || "").toLowerCase();
      const out = teachers.filter(t => !state.dutyPool.includes(t.id) &&
        (!ql || (t.name || "").toLowerCase().includes(ql) || (t.abbr || "").toLowerCase().includes(ql))).slice(0, 25);
      dutyDropdown.innerHTML = "";
      if (!out.length) {
        dutyDropdown.appendChild(el("div", { class: "chrx-sub-opt is-empty" }, "No matches."));
        return;
      }
      for (const t of out) {
        dutyDropdown.appendChild(el("div", { class: "chrx-sub-opt",
          onclick: () => {
            if (!state.dutyPool.includes(t.id)) state.dutyPool.push(t.id);
            dutySearch.value = "";
            dutyDropdown.classList.add("is-hidden");
            renderDutyChips();
          } },
          el("span", { class: "chrx-sub-opt__nm" }, t.name || t.id),
          t.abbr ? el("span", { class: "chrx-sub-opt__abbr" }, t.abbr) : null,
        ));
      }
    }
    dutySearch.addEventListener("focus", () => { buildDutyOptions(dutySearch.value); dutyDropdown.classList.remove("is-hidden"); });
    dutySearch.addEventListener("input", () => buildDutyOptions(dutySearch.value));
    host.appendChild(el("div", { class: "chrx-sub-row chrx-sub-row--col" },
      el("label", { class: "chrx-sub-lbl" }, "🛡 On-duty pool"),
      dutyChips,
      el("div", { class: "chrx-sub-search-wrap" }, dutySearch, dutyDropdown),
    ));
    renderDutyChips();

    // ---- generate button ----
    const generateBtn = el("button", { class: "chrx-sub-btn chrx-sub-btn--primary",
      onclick: () => generate(state, onGenerate, summary),
    }, "Generate substitutions");

    const summary = el("div", { class: "chrx-sub-summary" });

    host.appendChild(el("div", { class: "chrx-sub-row chrx-sub-row--actions" },
      generateBtn, summary,
    ));

    function updateGenerate() {
      const day = S.ymdToDay(state.date);
      generateBtn.disabled = state.absent.length === 0 || day < 0;
      generateBtn.title = day < 0
        ? "Sunday — pick a school day."
        : (state.absent.length ? "" : "Pick at least one absent teacher.");
    }

    renderChips();
    updateGenerate();
  }

  function generate(state, onGenerate, summaryEl) {
    const day = S.ymdToDay(state.date);
    if (day < 0) return;
    if (!state.absent.length) return;

    const school = APP.school;
    // Build the day's plan (one slot per absent card), then let the policy fill
    // what it safely can. Both steps live in main.js/planner_model.js so the
    // class-wise board, the toolbar and this button all drive the same engine.
    const plan = S.buildPlan(school, state.date, { absentIds: state.absent });
    plan.absent = state.absent.slice();
    plan.absentTypes = Object.fromEntries(
      state.absent.map((teacherId) => [teacherId, state.absentType || "Sick"])
    );
    plan.dutyPool = (state.dutyPool || []).slice();
    state.dutyPool = plan.dutyPool;

    const preview = S.planSmartFill(school, plan);
    S.applySmartFill(school, plan, preview);
    // applySmartFill published the FILLED plan; re-publishing `plan` here would
    // put the pre-fill (all-PENDING) copy back and erase the assignments.
    state.slots = preview.plan.slots;
    if (summaryEl) {
      const counts = window.SmartPlanner.planCounts(plan);
      summaryEl.textContent = `${counts.filled} filled · ${counts.pending + counts.reschedule} open`;
    }

    if (window.APP?.editor) {
      window.APP.editor.date = state.date;
      const editorDateInput = document.getElementById("editor-date-input");
      if (editorDateInput) editorDateInput.value = state.date;
    }

    window.dispatchEvent(new CustomEvent("substitution:generate", { detail: {
      date: state.date,
      absentTeachers: state.absent.slice(),
      assignments: (state.assignments || []).slice(),
    } }));

    if (summaryEl) {
      const n = state.assignments.length;
      const filled = state.assignments.filter(a => a.chosen).length;
      summaryEl.innerHTML = `<span class="chrx-sub-ok">Generated <b>${n}</b> slot(s); <b>${filled}</b> filled, <b>${n - filled}</b> uncovered.</span>`;
    }
    if (typeof onGenerate === "function") setTimeout(onGenerate, 50);
  }

  window.SubstitutionAbsence = { render };
})();

// [vite-esm] exports auto-generated by the 2026-07 Vite migration.
export const SubstitutionAbsence = window.SubstitutionAbsence;
